const fixtureData={players:[{id:'player-1',surname:'Rossi',name:'Marco',role:'Centrocampista',active:true,user_id:'demo-user'},{id:'player-2',surname:'Bianchi',name:'Luca',role:'Difensore',active:true,user_id:'demo-user'}],sessions:[{id:'session-1',user_id:'demo-user',session_date:'2026-10-06',session_type:'Allenamento',note:'Preparazione partita'}],attendance:[{id:'attendance-1',user_id:'demo-user',session_id:'session-1',player_id:'player-1',status:'Presente',delay_minutes:0},{id:'attendance-2',user_id:'demo-user',session_id:'session-1',player_id:'player-2',status:'Assente',delay_minutes:0}],matches:[{id:'match-1',user_id:'demo-user',match_date:'2026-10-11',opponent:'Squadra ospite',venue:'Casa',goals_for:2,goals_against:1,note:'Appunti dimostrativi della partita'}],match_events:[{id:'event-1',user_id:'demo-user',match_id:'match-1',player_id:'player-1',minute:24,event_type:'Gol',detail:'Conclusione dal limite',created_at:'2026-10-07T12:00:00Z'}]};
const fixtureUser={id:'demo-user',email:'demo@example.test',app_metadata:{role:'admin'}};
let fixtureNext=0;
class FixtureQuery {
 constructor(table){this.table=table;this.filters=[];this.action='select';this.rows=null;this.orders=[]}
 select(){return this} eq(key,value){this.filters.push(row=>row[key]===value);return this} order(key,options={}){this.orders.push({key,ascending:options.ascending!==false});return this}
 insert(rows){this.action='insert';this.rows=Array.isArray(rows)?rows:[rows];return this}
 upsert(row,options={}){this.action='upsert';this.rows=row;this.conflict=options.onConflict;return this} update(row){this.action='update';this.rows=row;return this} delete(){this.action='delete';return this}
 single(){this.one=true;return this} range(start,end){this.bounds=[start,end];return this}
 async result(){const table=fixtureData[this.table]||[];let rows=table.filter(row=>this.filters.every(f=>f(row)));if(this.action==='upsert'){let existing=table.find(r=>r[this.conflict]===this.rows[this.conflict]);if(existing){Object.assign(existing,this.rows);rows=[existing]}else{rows=[{...this.rows,id:'test-'+(++fixtureNext)}];table.push(...rows)}}if(this.action==='insert'){rows=this.rows.map(row=>({...row,id:'test-'+(++fixtureNext),created_at:new Date().toISOString()}));table.push(...rows)}if(this.action==='update'){rows.forEach(row=>Object.assign(row,this.rows))}if(this.action==='delete'){fixtureData[this.table]=table.filter(row=>!rows.includes(row))}if(this.orders.length)rows.sort((a,b)=>{for(const o of this.orders){const delta=String(a[o.key]??'').localeCompare(String(b[o.key]??''));if(delta)return o.ascending?delta:-delta}return 0});if(this.bounds)rows=rows.slice(this.bounds[0],this.bounds[1]+1);return {data:this.one?rows[0]:rows.map(row=>({...row})),error:null}}
 then(resolve,reject){return this.result().then(resolve,reject)}
}
window.fixtureData=fixtureData;
window.fixtureUser=fixtureUser;
window.confirm=()=>true;
window.fixtureRpcCalls=[];
fixtureData.attendance_history=[];
fixtureData.activities=[{id:'activity-1',user_id:'demo-user',activity_date:'2026-10-11',activity_type:'Partita',title:'Squadra ospite',status:'Programmato',revision:0,match_id:'match-1',start_time:'15:00',meeting_time:'14:00',location:'Campo comunale',meeting_place:'Sede squadra',organization_note:'Portare divisa blu'}];fixtureData.activity_roster=[];fixtureData.player_administration=[];fixtureData.activity_technical=[];
window.fixtureTeamCalls=[];

const fixtureRpc=async(name,payload)=>{if(name==='team_context')return {data:{owner_id:fixtureUser.id,role:fixtureUser.app_metadata.role==='admin'?'admin':fixtureUser.app_metadata.role||'manager'},error:null};if(name==='save_team_activity'){window.fixtureTeamCalls.push(JSON.parse(JSON.stringify(payload)));if(window.fixtureSaveError)return {data:null,error:window.fixtureSaveError};let a=fixtureData.activities.find(a=>a.id===payload.p_id);if(!a){a={id:'new-activity-'+(++fixtureNext),user_id:fixtureUser.id,revision:0};fixtureData.activities.push(a)}Object.assign(a,payload.p_activity,{revision:a.revision+1});for(const row of payload.p_roster){let r=fixtureData.activity_roster.find(r=>r.activity_id===a.id&&r.player_id===row.player_id);if(r)Object.assign(r,row);else fixtureData.activity_roster.push({...row,id:'roster-'+(++fixtureNext),user_id:fixtureUser.id,activity_id:a.id})}if(payload.p_technical){let t=fixtureData.activity_technical.find(t=>t.activity_id===a.id);if(t)Object.assign(t,payload.p_technical);else fixtureData.activity_technical.push({...payload.p_technical,activity_id:a.id,user_id:fixtureUser.id})}return {data:{...a},error:null}}window.fixtureRpcCalls.push(JSON.parse(JSON.stringify(payload)));if(window.fixtureRpcGate)await window.fixtureRpcGate;if(window.fixtureSaveError)return {data:null,error:window.fixtureSaveError};let session=fixtureData.sessions.find(s=>s.id===payload.p_session_id);if(!session){session={id:'new-session-'+(++fixtureNext),user_id:fixtureUser.id,revision:0};fixtureData.sessions.push(session)}Object.assign(session,payload.p_session,{revision:(session.revision||0)+1,updated_at:new Date().toISOString(),updated_by:fixtureUser.id});for(const row of payload.p_attendance){let a=fixtureData.attendance.find(x=>x.session_id===session.id&&x.player_id===row.player_id);if(a){const before={status:a.status,delay_minutes:a.delay_minutes,notified:a.notified??null,note:a.note??null};if(JSON.stringify(before)!==JSON.stringify({status:row.status,delay_minutes:row.delay_minutes,notified:row.notified,note:row.note}))fixtureData.attendance_history.push({id:'history-'+(++fixtureNext),user_id:fixtureUser.id,session_id:session.id,player_id:row.player_id,actor_id:fixtureUser.id,entity:'attendance',action:'UPDATE',changed_at:new Date().toISOString(),before_data:before,after_data:{...row}});Object.assign(a,row)}else fixtureData.attendance.push({...row,id:'attendance-'+(++fixtureNext),session_id:session.id,user_id:fixtureUser.id})}return {data:{session:{...session}},error:null}};
window.supabase={createClient:()=>({from:table=>new FixtureQuery(table),rpc:fixtureRpc,auth:{getSession:async()=>({data:{session:{user:fixtureUser}}}),getUser:async()=>({data:{user:fixtureUser}}),onAuthStateChange:()=>{},signOut:async()=>{}},functions:{invoke:async(_,options)=>({data:options.body.action==='list'?{users:[{...fixtureUser,role:'admin',created_at:'2026-10-06T12:00:00Z'}],nextPage:null}:{user:{id:'new-demo-user'}},error:null})}})};

